/**
 * Placeholder functions for generating astrological interpretations.
 * You can replace the switch/case logic here with a real data structure 
 * or JSON importing in the future.
 */

export function getAspectInterpretation(p1Name: string, p2Name: string, aspectLabel: string): string {
  // Retorna um texto de placeholder para o uso interno.
  // Ex: "A Quadratura entre Sol e Lua..."
  
  const baseText = `Esta é uma interpretação para o aspecto de ${aspectLabel} entre ${p1Name} e ${p2Name}. `;
  
  if (aspectLabel === 'Conjunção') {
    return baseText + `A Conjunção indica uma fusão e intensificação das energias de ambos os astros. Eles agem como uma unidade, o que pode ser extremamente poderoso, mas requer consciência para não se tornar avassalador.`;
  }
  if (aspectLabel === 'Sextil') {
    return baseText + `O Sextil é um aspecto harmonioso que indica oportunidades, fluidez e talentos naturais que podem ser desenvolvidos. As energias colaboram de forma estimulante.`;
  }
  if (aspectLabel === 'Quadratura') {
    return baseText + `A Quadratura é um aspecto dinâmico de tensão. Exige ação, superação de obstáculos e ajustes. É uma fonte de grande energia e crescimento se a frustração for superada.`;
  }
  if (aspectLabel === 'Trígono') {
    return baseText + `O Trígono é o aspecto mais fluente e benéfico, indicando sorte, facilidade e talentos inatos. As energias fluem sem resistência, trazendo apoio mútuo.`;
  }
  if (aspectLabel === 'Oposição') {
    return baseText + `A Oposição traz polaridade e a necessidade de equilíbrio. Muitas vezes projeta-se nos relacionamentos, exigindo integração de energias opostas para evitar conflitos extremos.`;
  }

  return baseText + `Este aspecto marca uma importante interação energética em seu mapa.`;
}

const SUN_IN_SIGNS: Record<string, string> = {
  'Áries': `Sol em Áries – Áries é o Signo de Exaltação do Sol, por isso essa é a posição mais poderosa da esfera central. Aqui ele irradia uma força vital de intensidade inigualável, a qual proporciona à pessoa uma reserva maravilhosa de energia com a qual resiste aos ataques de doenças, e, caso adoeça, seus poderes recuperativos logo o libertarão das garras da doença. Pessoas com essa posição são propensas, principalmente, a febres, devido ao calor ardente do Sol em Áries. Como Áries rege a cabeça, às vezes o calor excessivo resseca o couro cabeludo de tal maneira que o cabelo não pode crescer e a pessoa se torna calva.`,
  'Touro': `O Sol em Touro – É uma posição favorável à prosperidade financeira, mas imprime também uma tendência para a extravagância, especialmente no se vestir, e leva a pessoa a gostar muito do sexo oposto, às vezes com resultados danosos. Fornece grande força física e a pessoa gosta muito de se exibir e ver suas proezas admiradas pelos outros. Touro rege a laringe e, portanto, o Sol em Touro aumenta o vigor dos órgãos vocais, o que proporciona à pessoa uma voz forte e agradável.`,
  'Gêmeos': `O Sol em Gêmeos – Gêmeos é um Signo mercurial e o terceiro da gama dos Signos, daí essa posição resultar numa influência mista do Sol, de Mercúrio e da 3ª Casa. Isso favorece a expressão de Mercúrio, pois esse é o Planeta que excita as cordas vocais e produz o som na laringe taurina; também favorece a escrita e as viagens; a Mente é abrilhantada pelo Sol em Gêmeos, e quando é necessário ou conveniente viajar, a pessoa ganha por isso, tanto fisicamente como mentalmente. Proporciona uma disposição agradável e afável que, geralmente, a faz benquista entre as pessoas com que se relaciona.`,
  'Câncer': `O Sol em Câncer – Câncer é o quarto Signo e é regido pela Lua, assim o Sol em Câncer é uma mistura das influências do Sol, da Lua e da 4ª Casa. No horóscopo natural (onde Áries é o Ascendente) Câncer se situa no nadir, e com o Sol aqui a vitalidade está no seu nível mais baixo; assim que com essa posição a pessoa está apta a se tornar indolente, mesmo quando não acometida de doença alguma. Ela tende a ser inofensiva e a evitar brigas, daí ser harmoniosa e agradável no lar, desde que não lhe peçam para trabalhar arduamente. Essa posição do Sol faz com que a primeira parte da vida seja infrutífera, mas atrai êxito nos últimos anos. Câncer é um Signo psíquico, daí o Sol em Câncer proporcionar uma tendência para o oculto, muitas vezes com experiências psíquicas.`,
  'Leão': `O Sol em Leão – O Sol em Leão proporciona uma natureza dominadora, com uma grande dose de autocontrole, um aguçado senso de honra e uma integridade infalível. A pessoa aspira a dirigir outras, mas desprezaria tirar a mínima vantagem ou fazer algo a outrem que não estivesse em estrita concordância com a regra de ouro; as afeições dela são profundas e duradouras. As pessoas com o Sol em Leão são firmes defensoras daqueles a quem amam, mas são igualmente fortes em suas aversões. Leão é o Signo que rege o coração e o que quer que as pessoas com o Sol em Leão façam, é feito com uma concentração de propósitos que compele ao sucesso. Elas fazem amigos de verdade, e se alguém for seu inimigo, um leonino provará ser mais honrado e magnânimo do que qualquer outro.`,
  'Virgem': `O Sol em Virgem – Essa é a combinação das influências solar, mercurial e da 6ª Casa. Mostra o intermediário bem-sucedido entre o produtor e o consumidor, sutil, extremamente rápido para ver as vantagens que levará na promoção dos negócios, agradável e sociável com todos aqueles de quem espera obter algum ganho, mas arrogante com seus empregados e companheiros de trabalho; facilidade para persuadir alguém e falar coisas boas, mas não necessariamente falsa; ela apenas procura ser o número um. O Sol em Virgem proporciona bons químicos, enfermeiros e médicos, não cirurgiões, mas clínicos; elas acreditam firmemente nos medicamentos, e medicamentos em abundância.`,
  'Libra': `O Sol em Libra – Libra é regida por Vênus e é o sétimo Signo, daí que o Sol em Libra combina a influência de Vênus com a do Sol e a da 7ª Casa, com o resultado de que a pessoa ama o(a) cônjuge tão devotadamente que exclui todas as demais pessoas; por conseguinte, pode-se dizer da pessoa com essa posição que, verdadeiramente, “seu Sol nasce e se põe” no(a) companheiro(a) de matrimônio. Libra é também o Signo de Exaltação de Saturno, e sua influência é aqui a melhor, pois acrescenta um elemento de construção à arte de Vênus. Isso se faz sentir como habilidade para a arquitetura e para os ramos mais delicados da construção decorativa, quando o Sol está em Libra. Essa posição proporciona, também, uma voz bonita, sonora, e um talento para o canto.`,
  'Escorpião': `O Sol em Escorpião – O Sol em Escorpião, quando bem-aspectado, proporciona grande energia, coragem e independência. Faz a Mente ativa e favorece o sucesso em ocupações com atividades iguais ou semelhantes às de cirurgião ou soldado. Também tende a melhorar as finanças depois do matrimônio, mas inclina à extravagância. O Sol afligido aqui proporciona à pessoa maneiras ríspidas e bruscas, um sentimento de que seu julgamento é melhor do que o dos outros, e uma tendência a tratar asperamente quem quer que seja ou o que quer que esteja em seu caminho. Muitas vezes isso a torna indiferente ao sofrimento, e pode transformar o cirurgião em um vivisseccionista.`,
  'Sagitário': `O Sol em Sagitário – Essa posição solar enseja ideais elevados e uma nobre disposição aspirante, que procura se elevar ao elevar os outros. Tende a fazer a pessoa benevolente, filantrópica, e, portanto, amada entre as pessoas com quem se relaciona. Ela, frequentemente, é alvo de distinções e indicações para cargos de confiança e missões de natureza delicada, e nenhuma outra escolha poderia ser melhor, pois tais pessoas são a alma da honradez. Essa posição também levará ao êxito em religião, em leis e em política, pois proporciona uma Mente expansiva, apropriada para enfrentar os maiores problemas da vida.`,
  'Capricórnio': `O Sol em Capricórnio – Esse é bom Signo que mostra que a pessoa prosperará na vida pela ajuda e boa vontade de outras em posição mais elevada que a dela; mostra que ela merecerá a confiança dessas pessoas e pode se sair bem numa posição de responsabilidade e confiança; faz dela uma pessoa cuidadosa, prudente, fiel e honesta. Juízes com essa posição não podem ser subornados, e administrarão justiça a todos, conforme a entendem. A posição proporciona grande amor pela lealdade, o que atrai para a pessoa o respeito e a estima de todos os de seu círculo.`,
  'Aquário': `O Sol em Aquário – Essa posição combina as influências de Sol, Urano e da 11ª Casa. Proporciona à pessoa uma percepção intuitiva da natureza interna das coisas, e a põe em contato com as forças e ideias dos reinos espirituais, o que a leva a adotar, quando possível, novos e avançados cultos ou métodos de cura, tais como a Naturopatia, Eletroterapia, Astroterapia, Cura Magnética, etc. Ela é atraída, também, para a pesquisa científica, e para religiões ultraintelectuais ou estranhas. Essa posição solar atrai muita popularidade e amigos fiéis dentre os que estão em condição de prestar favores e de ajudar outros a realizarem suas ambições.`,
  'Peixes': `O Sol em Peixes – Gera um temperamento retraído e favorece ao êxito em ocupações distantes do olhar público, tais como em prisões, hospitais, instituições de caridade, etc. Se a pessoa incorre na inimizade de outrem, ela será defendida a despeito de qualquer coisa que possam fazer para macular sua reputação. O Sol em Peixes imprime forte tendência para o psiquismo, a mediunidade e o ocultismo em geral.`
};

const MOON_IN_SIGNS: Record<string, string> = {
  'Áries': `A Lua em Áries proporciona um tipo de Mente muito independente, que almeja abrir seu próprio caminho na vida, seja correto ou não, e é extremamente suscetível em se ressentir por qualquer interferência dos outros. A pessoa é ambiciosa e agressiva, mas falta-lhe pensar ou planejar cuidadosamente antes de fazer algo, daí ser possível que tenha de enfrentar numerosos reveses. Todavia, essa posição proporciona uma coragem intrépida, razão pela qual tais pessoas não são facilmente derrotadas. Quando fracassam em uma direção, imediatamente tentam outro empreendimento e, por fim, a grande persistência delas, geralmente, as leva a se sobressaírem em sua área de atuação, as conduzindo ao sucesso, a menos que a Lua esteja afligida; nesse caso, elas têm a propensão a se voltar para uma ocupação após outra, sem se permitirem tempo para tentar, honestamente, o êxito em alguma específica.`,
  'Touro': `A Lua em Touro. Esse é o Signo de Exaltação da Lua e seu efeito é, portanto, muito poderoso para o bem, se ela está livre de aflição e bem aspectada. Então, a natureza do Signo Fixo de Touro reduz a volubilidade da Lua, que também se combina com o raio de Vênus. Isso resulta em uma disposição meiga, autoconfiante e determinada. Proporciona perseverança, previdência e bondade, assim a pessoa pode atrair todas as boas coisas da vida, tais como saúde e riqueza, amigos e família, casas e terras, com a habilidade de aproveitar todas essas coisas, pois a Lua em Touro faz com que goste muito dos prazeres, sociável e hospitaleira, uma apreciadora da arte, da música e de todas as outras coisas que constituem os deleites da vida.`,
  'Gêmeos': `A Lua em Gêmeos proporciona um intelecto bem alerta, inclinado para a literatura e para a ciência, cheio de recursos e capaz de enfrentar emergências; tolerante, liberal e atento para ideias progressistas, que são adotadas com avidez. Assim, tais pessoas são muito atraídas para ocupações literárias, particularmente no campo do jornalismo, em que podem pular de um assunto a outro, como requer sua Mente extremamente inquieta. Essa posição também proporciona uma atração muito forte e inusitada por viagens e um desejo por empregos que possibilitem contato com muitas pessoas. Favorece a ocupações tais como as de representante de vendas, empregada de comércio que viaja por conta de uma firma ou, se por conta própria, encarregada dos negócios de várias casas ou ramos, cabos eleitorais e atividades semelhantes.`,
  'Câncer': `A Lua em Câncer proporciona uma disposição que é bondosa, sociável e compassiva, mas indolente e avessa a esforços seja físicos, morais ou mentais. Essas pessoas apreciam muito vagar à toa, só se movendo sob o chicote da necessidade. Geralmente são sensíveis a condições psíquicas, especialmente se a Lua estiver aspectada por Netuno ou Urano, sendo a natureza do aspecto que determina se a influência é benéfica ou adversa. Essa posição proporciona, também, apego ao lar e aos seus confortos. Favorece a digestão e, consequentemente, a saúde, se a Lua estiver bem-aspectada. Se afligida, tende a provocar problemas digestivos.`,
  'Leão': `A Lua em Leão exerce uma influência iluminadora sobre a Mente. Proporciona uma disposição forte, autoconfiante, agressiva com habilidade para organização; portanto, pessoas com a Lua nessa posição, normalmente, conseguem a liderança em seu círculo imediato. São honradas nos assuntos financeiros e sociais, justas e magnânimas em seus relacionamentos com os outros e muito populares.`,
  'Virgem': `A Lua em Virgem incrementa as qualidades mentais, se estiver bem aspectada; ela proporciona uma memória retentiva, uma forte atração por estudos que sigam linhas científicas ou ocultistas, e uma ambição para se sobressair. Das ciências, a química é a favorita de tais pessoas, que podem se tornar excelentes dietistas (que lida com a preparação de alimentos para manutenção ou melhoria da saúde e excelentes químicos). São um tanto reservadas e de comportamento calmo, e se aborrecem com a adulação ou com a ostentação. A menos que se ocupem como dietistas, elas são mais bem sucedidas como servidoras ou empregadas dos outros do que como donas de seus próprios negócios.`,
  'Libra': `A Lua em Libra é uma posição afortunada para se fazer amigos e para popularidade pública, pois torna a pessoa bondosa, compassiva e agradável, otimista e amiga dos prazeres sociais. Essa posição proporciona uma boa capacidade de raciocínio e a habilidade para formar um julgamento correto, amor à arte e à música e, às vezes, uma habilidade considerável como intérprete, se assistido por outros.`,
  'Escorpião': `A Lua em Escorpião produz uma disposição corajosa, independente e energética. A pessoa que tem essa configuração não tolerará interferência em seus planos, nem se submeterá a imposições. Na maioria das vezes é muito ríspida em suas maneiras e áspera no falar, impaciente e não se deixando coagir por ameaças, mas singularmente sensível à bondade. Ela tem uma vontade forte e inflexível e determinação para realizar tudo o que se propõe. Essa posição, também, imprime uma atração considerável para as ciências ocultas, mas, se afligida, a Lua pode levar a excessos na gratificação dos sentidos, gerar problemas com mulheres ou dificuldades no parto.`,
  'Sagitário': `A Lua em Sagitário proporciona uma personalidade alerta e ativa, uma atração muito forte por caminhadas, por cavalgar ou por outra forma de exercício físico; uma tendência a ser nômade e uma atração muito forte por viajar por países estrangeiros; ternura por animais, especialmente por cavalos e cachorros, e uma inclinação para o estudo da religião, lei, filosofia ou ciência oculta. Essas pessoas são muito otimistas, bem-humoradas, joviais e companheiras ideais, a menos que a Lua esteja afligida, então, sua posição em Sagitário conduz à indolência e ao comodismo.`,
  'Capricórnio': `A Lua em Capricórnio, se bem-aspectada, proporciona uma abundância de ajuda de pessoas de classe social mais elevada, de modo que, qualquer êxito que possa ter vindo através dos outros, a pessoa é demasiadamente tímida para se pôr em evidência, além disso, sua inclinação para uma melancolia a torna extremamente sensível a imposturas, sejam esses reais ou imaginárias. Se a Lua está afligida, a pessoa tende a ficar sujeita a difamações, merecidas ou não. Essa posição exerce ainda efeito pernicioso sobre a digestão. Pessoas com a Lua nessa posição geralmente vivem com um medo insano de sofrer privações, tornando-se, portanto, avarentas e miseráveis, e negando a si mesmas todo o conforto do momento presente, para que possam ter algo em dias de escassez. Elas nutrem pouquíssimo sentimento por si próprias e absolutamente nenhum.`,
  'Aquário': `A Lua em Aquário, se bem-aspectada, proporciona à pessoa uma imaginação muito vívida e o poder de evocar imagens ante seus olhos mentais de modo a parecerem quase tangíveis; além disso, essas pessoas não dependem da faculdade da razão, pois sua intuição é, também, extremamente bem desenvolvida. Quanto à disposição, são sociáveis, agradáveis e cordiais, daí atraírem muitos amigos e serem muito populares em seu meio, sendo ajudados por seus amigos, de acordo com os Aspectos da Lua. Por outro lado, se a Lua estiver afligida, essa posição revela uma pessoa com uma Mente excessivamente errática.`,
  'Peixes': `A Lua em Peixes proporciona uma Mente receptiva e uma imaginação fértil, com uma disposição para a indolência e para a autocompaixão, para a vacilação e para a falta de ânimo; tende a fazer a pessoa gostar muito de sonhar em vez de agir, pelo que uma grade tristeza, problemas e a auto desgraça lhe faz experimentar sérios problemas ou perigos no caminho da vida. Essa posição, muitas vezes, leva à mediunidade, especialmente se Netuno forma Aspecto adverso, pois tais pessoas são peculiarmente sensíveis à bajulação dos espíritos de controle e à atração por tudo que possa excitar suas emoções. São também muito verbosas em sua maneira de se expressar. Se um bom Aspecto de Vênus e Mercúrio lhe conferir aptidão para a música, elas tocarão com extraordinária inspiração e sentimento. Se a Lua estiver afligida em Peixes, os assuntos amorosos podem ocasionar-lhes desgostos. Se Peixes estiver na 12ª Casa e a Lua também, no nascimento, os pais do nativo terão inclinação para bebidas alcoólicas e, assim eles negligenciaram seus filhos, os quais podem, por isso mesmo, ficar sob a tutela de instituições de caridade até atingirem a maioridade.`
};

const MERCURY_IN_SIGNS: Record<string, string> = {
  'Áries': `Mercúrio em Áries tende a deixar a pessoa muito argumentativa, apaixonada pelas discussões, rápida nas conversas que são cheias de comentários inteligentes e respostas divertidas, com uma tendência a exagerar, embora não necessariamente com tal intenção. Se bem-aspectado, Mercúrio proporciona uma Mente aberta e tolerante às opiniões dos outros, com uma natureza estudiosa, rápida no compreender as situações e ideias, simples e organizada. Quando afligido, Mercúrio em Áries leva as pessoas a passar por cima antes de olhar; a Mente é vacilante e a pessoa é, de modo geral, negligente, pelo que ela se torna muito não confiável e destituída de todo senso de responsabilidade.`,
  'Touro': `Mercúrio em Touro proporciona uma Mente que não se decide com rapidez, mas que quando chega a uma conclusão é quase tão difícil mudá-la quanto mudar as leis dos Medas e Persas. Contudo, sendo baseado no pensamento e no raciocínio, o critério dessas pessoas é extremamente confiável. Elas acreditam totalmente no velho adágio de que “o silêncio é de ouro”, e, portanto, são extremamente discretas. São boas conselheiras e nelas podemos confiar para guardar um segredo. Ao mesmo tempo, não se isolam, mas possuem uma disposição agradável e sociável. Apreciam o divertimento e a recreação, amam a música, arte e literatura, de modo que são pessoas muito admiradas, se Mercúrio está com Aspectos benéficos. Contudo, se Mercúrio está com Aspectos adversos, se convertem em obstinados, teimosos, reservados e avarentos.`,
  'Gêmeos': `Mercúrio em Gêmeos tende a fazer a pessoa gostar de mudanças e de viagens. Ela está sempre pronta para investigar alguma coisa nova ou para ir a algum outro lugar só pelo prazer de mudar; em suma, quase tudo o que é novo lhe interessa. Ao mesmo tempo, se Mercúrio está bem fortalecido tais pessoas ganham muito por esse estado fluídico da Mente, pois são engenhosas e penetrantes em seus julgamentos, de tal maneira que sabem avaliar bem, não se deixando influenciar por opiniões assentadas e preconcebidas. Em consequência, são boas negociantes e suas habilidades em ver uma questão faz delas, particularmente, boas advogadas. São igualmente bem-sucedidas como representante de vendas, empregada de comércio que viaja por conta de uma firma ou, se por conta própria, encarregada dos negócios de várias casas ou ramos.`,
  'Câncer': `Mercúrio em Câncer proporciona um intelecto claro, uma boa memória e adaptabilidade superlativa. As pessoas com essa posição se enquadram a qualquer lugar ou ocupação que possam encontrar, e se adaptam às opiniões e às ideias dos outros. Gostam de ser elogiadas e aduladas, portanto, cuidam de não fazer algo que possa comprometer a boa opinião dos outros.`,
  'Leão': `Mercúrio em Leão proporciona ideais e aspirações elevados, um intelecto construtivo, forte e perseverante, que despreza descer aos atos baixos e mesquinhos, e menospreza os equívocos; é uma pessoa franca e direta, irritadiça, mas de bom coração e compassiva. Pessoas com Mercúrio bem fortalecido em Leão possuem boa capacidade de organização e são líderes competentes. Amam crianças e gostam muito dos prazeres. Quando Mercúrio está afligido em Leão torna a pessoa volúvel e inconstante em suas afeições; resulta no jogador e no especulador fracassado, de natureza inferior e sensual.`,
  'Virgem': `Mercúrio em Virgem está no zênite do seu poder, pois aqui ele está Exaltado e, consequentemente, quando bem-aspectado proporciona uma Mente clara, lógica e científica, com eloquência e habilidade para se expressar fluentemente em várias línguas. Provê para pessoa uma visão compreensiva e com bom discernimento da vida; suas conclusões são geralmente práticas e objetivas porque, à semelhança de Mercúrio em Touro, ela também é sensata em pesar sobre os possíveis perigos ou as dificuldades antes de fazer algo ou tomar uma decisão. Em resumo, essa característica é, em certa medida, verdadeira para todos os Signos de Terra. Quando Mercúrio está afligido em Virgem deixa o ser humano irritável, petulante e egoísta, sempre em busca de defeitos em tudo que encontra. Pessoas com Mercúrio em Virgem tendem a ser excelentes nutricionistas especializada em dieta – dietistas – que lida com a preparação de alimentos para manutenção ou melhoria da saúde e excelentes químicos. Possuem, também, a destreza incomum.`,
  'Libra': `Mercúrio em Libra, quando bem-aspectado, proporciona uma Mente aberta, bem equilibrada, com um amor pela arte e pela música e uma habilidade incomum de expressão. Proporciona sucesso como um orador público e, às vezes, como um cantor. Quando Mercúrio está afligido em Libra, indica problemas devidos a ações judiciais advindas de sociedades e de cônjuge infiel.`,
  'Escorpião': `Mercúrio em Escorpião proporciona uma Mente engenhosa, forte aspiração, uma habilidade para dizer rapidamente coisas que são claras e divertidas e uma língua ferina, com um sarcasmo mordaz que pica como o escorpião. A disposição é corajosa, teimosa, obstinada e isso dificulta o convívio com tais pessoas. Contudo, essas pessoas são extremamente boas em encontrar meios para lidar com os problemas práticos, confiantes e não se assustam facilmente e capazes de superar dificuldades que subjugariam a outros. São atraídas para o ocultismo como uma agulha para um imã. Quando Mercúrio está afligido, ficam sujeitas a decepções em tudo o que se propõem, tornam-se briguentas, céticas e cínicas, mantendo-se sempre contrárias aos pontos de vista dos outros.`,
  'Sagitário': `Mercúrio em Sagitário. Mesmo estando em Detrimento, essa é ainda uma posição forte de Mercúrio, de modo que, se bem-aspectado, ele proporciona uma Mente extremamente nobre, voltada para a religião e para a filosofia; uma Mente que despreza as algemas das convenções onde quer que elas interfiram na liberdade de pensamento e de palavra, embora não enverede por caminhos contrários aos padrões de hábitos e de condutas morais comumente aceitos. Sempre dentro dos limites da lei e da ordem, as pessoas com Mercúrio nessa posição são, portanto, muito respeitadas na comunidade. Mercúrio em Sagitário tende a fazer com que a pessoa aprecie muito viagens, para ver paisagens e cenários da natureza e para investigar os costumes de outros povos. Também se afeiçoa aos animais e animais domésticos. Quando afligido, inclina para a marginalidade, desonestidade, a praticar a mania de argumentar algo que procura induzir os outros ao erro e para um caráter deturpado.`,
  'Capricórnio': `Mercúrio em Capricórnio proporciona uma Mente crítica e penetrante, mas um tanto desconfiada com uma disposição ponderada e diplomática. Essas pessoas se tornam esplêndidos espiões e detetives, tendo a habilidade de arrancar segredos da maneira mais insólita. Possuem, também, a persistência dos saturninos, derivada do Signo de Capricórnio, de modo que jamais desistem antes de alcançar seu objetivo. Essa posição produz um amor pela ciência, especialmente pela química. Essas pessoas são muito atraídas para o ocultismo, embora sejam práticas e muito econômicas. São muito apegadas ao que conseguem, e sempre prevenidas para ocasiões difíceis. Quando afligido, Mercúrio em Capricórnio tende a tornar a pessoa avarenta, cruel, dura, maliciosa, vingativa e rancorosa.`,
  'Aquário': `Mercúrio em Aquário proporciona as qualidades uranianas de originalidade e independência e um inquebrantável amor à liberdade da Mente, de modo que as pessoas com Mercúrio nessa posição são capazes de repudiar todas as convenções sociais e de viver consoante suas concepções altamente idealistas. É comum não ligarem para a moda, e se vestirem com um style próprio. Advogam ideias sobre assuntos sociais que estão mil anos à frente do desenvolvimento do mundo, entre as quais a teoria das almas gêmeas e das afinidades, que está causando tantos problemas no mundo de hoje, pois seus defensores ainda não cresceram em estatura espiritual de modo a poder separá-la do sexo e a viver a verdadeira vida uraniana de amor, que é inteiramente espiritual. As delineações acima se aplicam particularmente quando Mercúrio está aspectado por Urano, e as pessoas descritas por elas são o produto extremo de Mercúrio em Aquário. Todas que têm essa posição, contudo, são muito intelectualizadas, alimentam ideais e aspirações elevadas, amor pela sabedoria popular e pela matemática, e geralmente são atraídos também para as ciências ocultas, especialmente para a astrologia, pois possuem a faculdade admirável de ler horóscopos. São bondosos, sociáveis e gostam muito de amigos, pelo que geralmente atraem grande número de intelectuais ao seu círculo de conhecidos. Mercúrio afligido nessa posição tende a tornar a pessoa desleal e pronta para irritar seus amigos, ou a criticá-los e caluniá-los.`,
  'Peixes': `Mercúrio em Peixes, o oculto Signo de Água, parece dotar a Mente com uma certa faculdade psíquica, que não é tanto intuição quanto imaginação. Essas pessoas pensam ou imaginam que tal coisa deve ser desta ou daquela maneira, e o fato surpreendente é que geralmente estão certas; mas, essa habilidade as deixa perigosamente próximas à mediunidade, se Mercúrio estiver aflito, ou quando Netuno, a oitava superior de Mercúrio, estiver na 12ª Casa. Portanto, essa posição é bastante perigosa. Se Mercúrio estiver afligido por Saturno, essa posição em Peixes inclina a pessoa ao pessimismo e a Mente estará sujeita a constantes preocupações com uma tendência à melancolia. Geralmente pessoas com Mercúrio em Peixes são de disposição gentil e benevolente. É também boa indicação de que o sucesso pode ser alcançado na química, e como de nutricionista especializada em dieta – dietistas – que lida com a preparação de alimentos para manutenção ou melhoria da saúde na preparação de alimentos saudáveis.`
};

const VENUS_IN_SIGNS: Record<string, string> = {
  'Áries': `Vênus em Áries empresta um forte calor intenso às afeições de Vênus ao misturá-las com o fogo de Marte, regente de Áries, e, por essa razão, torna a pessoa muito ardente na expressão do afeto. Isso, geralmente, conduz à popularidade, especialmente entre o sexo oposto, e, frequentemente, resulta em casamentos precipitados; mas esse tipo de amor não é nem pode ser duradouro. Finalmente, o fogo da paixão desgasta o amor, e os casamentos realizados desse jeito são fontes abundantes de infelicidade doméstica. Essa posição também inclina a pessoa a ser imprudente e impulsiva onde quer que a levem suas simpatias, de maneira que é comum ela atuar em favor de uma causa injusta. Vênus em Áries também inclina a pessoa à extravagância geral em seus gastos.`,
  'Touro': `Vênus em Touro é uma posição esplêndida, pois aqui ele está Essencialmente Dignificado e muito mais forte do que em outros Signos, com exceção de em Libra e Peixes, onde está, respectivamente, Essencialmente Dignificado e Exaltado. É uma posição muito favorável aos negócios financeiros, especialmente para ganhos oriundos dos próprios esforços da pessoa, em qualquer vocação que tenha escolhido na vida. Proporciona uma disposição amistosa e sociável com habilidade para inspirar sentimentos recíprocos nos outros. Pessoas com Vênus em Touro são muito firmes em suas opiniões, concernentes à forma certa e ao decoro, corretas no falar, e uma vez formada sua opinião, a ela se apegam com muita tenacidade. São generosas, mas não extravagantes.`,
  'Gêmeos': `Vênus em Gêmeos combina a beleza de Vênus com a habilidade mercurial de se expressar, de maneira que pessoas com essa configuração são capazes de escolher suas palavras com uma facilidade singular, e de lhes infundir um ritmo que é como música para os ouvidos de quem as escuta. Em consequência, essa é uma das posições que fazem poetas, desde que, naturalmente, apoiada por outras indicações no horóscopo, pois o Estudante deve se lembrar sempre que nenhum Aspecto ou posição por si só é suficiente para assinalar uma característica proeminente. Para fazer isso, todo o horóscopo deve ser combinado. Essa posição exerce uma influência muito refinadora sobre a Mente, inclinando-a à carreira literária ou artística. Tende a fazer a pessoa amada por seus irmãos e irmãs, vizinhos e outras pessoas em seu meio ambiente. Essa posição também inclina ao casamento e, frequentemente, conduz a mais de uma união. Favorece viagens, tanto as de negócios quanto as de lazer, especialmente viagens curtas.`,
  'Câncer': `Vênus em Câncer combina as características de Vênus com as da Lua e com a natureza aquática e psíquica de Câncer. Por esse motivo, essa posição proporciona à pessoa uma imaginação muito fértil, de modo que ela é muito capaz de entrar em contato com os habitantes dos Mundos invisíveis ou, pelo menos, de passar uma fase a se dedicar bastante à religião; contudo, isso é perigoso, pois sendo Vênus de natureza negativa, atrai sem escolher nem discriminar, pelo que pode sujeitá-la ao domínio de espíritos de controle e aos perigos da mediunidade.`,
  'Leão': `Vênus em Leão é um composto de amor, pois Leão rege o coração, de modo que, com essa posição a pessoa terá, em certa medida, um coração muito terno. Contrariamente às ideias comumente aceitas, há em Leão um elemento cruel, mas quando Vênus lá está, não existe nenhum outro Signo tão amoroso e terno no Zodíaco; além disso, sendo Leão um Signo Fixo, Vênus nessa posição favorece uma afirmação do afeto sem paralelo, quando uma vez manifestado, e uma lealdade inabalável ao objeto em apreço. Sendo Leão o quinto Signo, Vênus em Leão também favorece o sucesso em empreendimentos de diversões ou educação, e a combinação do raio de Vênus com o solar atrai o favor daqueles que estão acima da pessoa na escala social.`,
  'Virgem': `Vênus em Virgem, o Signo da 6ª Casa, confere à pessoa uma simpatia carinhosa e profunda pelos doentes, de maneira que as pessoas com essa posição podem se tornar bons enfermeiras. Essa posição, também, favorece ocupações como a de químico, ou de nutricionista especializada em dieta – dietistas – que lida com a preparação de alimentos para manutenção ou melhoria da saúde. Se a pessoa tem empregados ou pessoas subordinadas à sua orientação, seu relacionamento com eles será sempre muito agradável, e eles a servirão bem.`,
  'Libra': `Vênus em Libra, no Signo da 7ª Casa ele está Essencialmente Dignificado e muito forte. Essa é uma das posições que garantem um casamento fértil e apropriado, ou uma sociedade bem-sucedida. Confere habilidade musical e artística e torna a pessoa popular na vida pública. Se se dedica a ser locutor ou cantor, terá garantida uma grata audiência todas as vezes que aparecer em público.`,
  'Escorpião': `Vênus em Escorpião é a pior de todas as posições em que ele pode ser colocado, pois aqui novamente o raio de amor de Vênus se mistura com o fogo marciano da paixão no Signo que governa os genitais, de modo que, se não houver nenhuma outra influência redentora e restritiva no horóscopo, o amor pode se converter em luxúria e em satisfação desenfreada do desejo sexual exagerado, especialmente se a Lua ou Marte estiverem ali. Isso promove uma tendência natural a enfraquecer a saúde e a habilidade do corpo em lutar contra as doenças e, embora possa não ser aparente por muito tempo, o efeito de tal desgaste da vitalidade um dia será sentido, podendo causar um colapso geral; contudo isso, naturalmente, não é nada comparado ao efeito moral das práticas indicadas por essa paixão. Deve-se dizer, para o bem daqueles com essa posição, que não importa se tais abusos são praticados dentro ou fora do casamento; à Natureza não importa se eles foram legalizados ou não pela “lei do homem”. Do seu ponto de vista, os abusos constituem uma violação da lei da vida, devendo, pois, ser punidos quer tenham sido sancionados pela sociedade ou não. Essa posição também gera um amor pelo luxo e a atração por tudo o que mexa com as emoções ou por aquilo em que os sentidos possam se deleitar. Curiosamente é que, às vezes, confere também um sentimento de profunda devoção religiosa, o qual serve como uma válvula de escape para os sentimentos sobrecarregados do nativo. Essa posição cria, ainda, ciúmes e problemas no casamento, e uma tendência da difamação da reputação da pessoa. Vênus em Escorpião, quando bem aspectado, pode trazer um legado.`,
  'Sagitário': `Vênus em Sagitário. Essa é outra posição muito forte de Vênus, pois aqui suas qualidades se misturam com as de Júpiter, o Planeta da benevolência, para fomentar o amor e a boa vontade entre os seres humanos. Portanto, essa posição indica também uma disposição cordial e otimista, um coração compassivo, bondoso e generoso, um amor a Deus expresso por meio da devoção religiosa, ou um amor ao ser humano demonstrado por meio da filantropia e da caridade. Indica uma Mente refinada, culta e apreciadora do drama, da arte e da música. Fomenta a imaginação e a intuição e, como os outros Signos duplos, Gêmeos e Peixes, tende à pluralidade de casamentos.`,
  'Capricórnio': `Vênus em Capricórnio, o Signo da 10ª Casa, favorece o sucesso social e a popularidade, mas Vênus não combina bem com Saturno, o Regente de Capricórnio. Por conseguinte, existe uma leve tendência à melancolia nas pessoas com Vênus nessa posição. Também nem sempre estão seguras dos favores que recebem de outras pessoas ou de sua popularidade, pois Saturno tende a derrubá-las quando elas atingem o ponto culminante. Portanto, embora essa influência possa ajudá-las a galgar a escada do progresso nos círculos sociais ou nos negócios, jamais estarão seguras em sua posição. Tal influência torna a pessoa muito zelosa de sua honra, de modo que se ressente quando, às vezes, Saturno a derruba. Vênus no Signo de Saturno, frequentemente, leva a pessoa a desconsiderar o fact de que a diferença de idade pode ser fatal à felicidade do casamento, pelo que, se se casa cedo, procura um cônjuge muito mais velho, e se se casa mais tarde, escolhe alguém muito mais jovem, resultando disso, inevitavelmente, a desagregação e o rompimento do laço matrimonial em poucos anos. É frequente, também, as pessoas com essa posição de Vênus se casarem por interesse nos negócios ou por conveniência. Em resumo, Vênus nunca alcança sua expressão legítima de amor na Casa de Saturno, sendo, portanto, tais uniões sempre uma fonte de tristeza e de decepção para ambas as partes.`,
  'Aquário': `Vênus em Aquário indica uma combinação das qualidades Uranianas de independência, impaciência às restrições, desconsideração ao convencionalismo, desejo de originalidade, sinceridade desinteressada e intuição, com as qualidades de Vênus e, como resultado, vemos que as pessoas com essa posição se recusam a se sujeitar às habituais regras limitadoras da sociedade em seus casos de amor, antes seguindo a inclinação de seus corações, indiferentes ao que os demais possam dizer ou pensar. Acreditam firmemente na teoria das almas gêmeas, das afinidades, etc., e são capazes de agir de modo tão inesperado e com rapidez tão surpreendente que nem elas nem os outros são capazes de prever o que poderão dizer ou fazer em seguida. No entanto, ao mesmo tempo são tão amorosas e sinceras em suas convicções que os amigos nunca as enganam, e qualquer sucesso que obtêm na vida se deve, geralmente, aos esforços dos amigos, os quais as ajudam a realizar suas esperanças, seus desejos e suas aspirações.`,
  'Peixes': `Vênus em Peixes está em seu próprio Signo de Exaltação, onde novamente se combina com o raio benéfico de Júpiter, e, como Peixes é um Signo da Água, essa posição significa uma poderosa natureza emocional, reprimida e diminuída pelo elemento da tristeza inerente ao Signo da 12ª Casa. Essa posição, portanto, indica alguém capaz de sentir algo semelhante ao que sentiu nosso Salvador quando disse: “Vinde a Mim todos vós que estais cansados e oprimidos, e Eu vos aliviarei.”. Assim, Vênus em Peixes indica uma natureza ansiosa e pronta para ajudar os que sofrem com as doenças do corpo ou que sofrem amarguras. Movidas pela compaixão, tais pessoas geralmente trabalham em prisões ou em instituições de caridade, onde encontram uma válvula de escape para essa compaixão. Essa posição também infunde intenso amor pela música, e quando existem outras evidências, confere habilidade considerável tanto vocal como instrumentalmente, pois a música é o mais belo meio de expressão para as emoções mais profundas que a alma humana é capaz de sentir. As pessoas com Vênus em Peixes estão particularmente sujeitas a depender financeiramente dos outros e a problemas resultantes de um casamento ilegal.`
};

const MARS_IN_SIGNS: Record<string, string> = {
  'Áries': `Marte em Áries proporciona uma natureza repleta de energia e determinação, entusiasmada, impulsiva, agressiva e impaciente diante de restrições. Não importa quais sejam os obstáculos no caminho, essas pessoas tentarão o aparentemente impossível e, muitas vezes, alcançarão sucesso por pura audácia. São originais, engenhosas, com considerável habilidade mecânica, de modo que quanto mais arriscado um empreendimento pareça, mais atraentes será para elas. Essa posição proporciona uma abundância de vitalidade e um amor pelos esportes e pelos exercícios musculares. A pessoa é tão entusiasta no desfrutar das recreações e dos divertimentos como o é em seu trabalho, conseguindo muito da vida por tal motivo. Contudo, Marte afligido em Áries TES produz uma forte tendência a se tornar zangada de repente e facilmente e a possibilidade de sofrer acidentes, queimaduras, escaldaduras, febres e males inflamatórios. A Mente também tem tendências a ser se posicionar como ameaça ou se sentir ameaçada.`,
  'Touro': `Marte em Touro e bem-aspectado é boa indicação de um casamento precoce. Demonstra boa capacidade de ganhar dinheiro e uma disposição livre e generosa com respeito a finanças; proporciona uma força interior de natureza invencível, força que fará a pessoa alcançar seus objetivos em virtude de uma determinação inquebrantável e de uma persistência calma que não admite fracasso, mas compele em direção à meta que ela impôs a si própria a despeito de todos os obstáculos. É indicação também de dinheiro por herança. No entanto, se Marte estiver afligido em Touro, então proporciona uma natureza excessivamente teimosa, violenta e vingativa. Tais pessoas forjarão seu próprio caminho a despeito de razões, argumentos ou súplicas, e, se alguém tenta impedi-las em seus propósitos, elas nunca esquecem. Também têm grande capacidade para ganhar dinheiro, mas esbanjam-no tolamente, e assim sofrem dificuldades financeiras frequentemente; e se recebem alguma herança, é mais provável que a percam por problemas legais; e, também, elas terão problemas domésticos.`,
  'Gêmeos': `Marte em Gêmeos quando bem-aspectado proporciona uma mentalidade rápida para compreender as coisas, ativa e atenta. Pessoas com Marte nessa posição vão sempre direto ao ponto, não enrolam. São honestas, francas e dizem exatamente o que pensam, às vezes um pouco até muito bruscamente, mas de qualquer modo não são hipócritas. Adoram medir sua habilidade ou inteligência com outros em um debate, pelo que essa posição proporciona êxito em atividades que mexam com leis ou na literatura. Também podem alcançar sucesso como engenheiras, pois são férteis em recursos, engenhosas e mecânicas, aptas a aprender e rápidas no entender um problema ou sugestão. Porém, se Marte está afligido em Gêmeos, ele proporciona um temperamento cínico, zombeteiro, que gosta de criticar de uma maneira cruel e sarcástica e que faz com que essas pessoas sejam temidas e evitadas, em razão de sua natureza desagradável. Também são vacilantes e incapazes de tomar uma decisão. Por isso não são confiáveis, não cumprem sua palavra nem suas promessas, e se alguma vez mantêm um compromisso, isso acontece por acidente. Tais pessoas sempre têm problemas com irmãos, irmãs e vizinhos e estão sujeitas a acidentes em viagens. Também resulta em predisposição a bronquites, inflamação dos pulmões, pleurisia e pneumonia.`,
  'Câncer': `Marte em Câncer e bem-aspectado proporciona uma natureza que não tem medo de correr riscos e toma decisões difíceis, independente e que não tem medo de nada, com uma tendência à rebeldia contra as restrições; um temperamento que aprecia gastar seu tempo no cuidado com o lar e com a família, ao invés de sair com os amigos ou viajar para outros lugares; pessoas que trabalham com muito afinco, são determinadas a serem bem-sucedidas em ter as coisas, e a garantir tudo o que proporcione conforto e luxo, e é por isso que são hábeis no abastecimento do lar em todos os aspectos. Entretanto e ao mesmo tempo, as pessoas com esse posicionamento de Marte almejam exercer irrestrita autoridade sobre tudo e todos dentro do lar. Elas não toleram outra autoridade. Essa posição proporciona um humor ou um estado emocional variável e uma tendência e um desejo de mudar de ocupação; assim, a pessoa nunca se fixa em uma linha de trabalho, mas assume diversas atividades e as abandona repentinamente. Se Marte estiver afligido em Câncer, ele pode ocasionar problemas domésticos, cenas frequentes de violência e discussões no lar, com uma tendência para se mudar, frequentemente, de um lugar para o outro; tendências a ter doenças inflamatórias do estômago e distúrbios digestivos; também a sofrer acidentes com fogo no lar, devido à imprudência ou ao descuido.`,
  'Leão': `Marte em Leão e bem aspectado proporciona uma natureza ativa, laboriosa e honesta, destemida e independente em tudo ao lidar com os outros; um agudo senso de honra e de responsabilidade, o que faz a pessoa eminentemente adequada para ocupar posições de confiança, tanto na área privada quanto na pública. Essas pessoas têm muita energia e determinação e são entusiastas tanto no trabalho como no divertimento; amam o esporte e, geralmente, gostam de se divertir. Demonstram fortemente os sentimentos positivos em sua admiração com relação ao sexo oposto, e cortejam o objeto de suas afeições com uma intensidade que ultrapassa a tudo, vencendo todos os obstáculos e levando o assunto a uma rápida consumação. Essas pessoas nunca fazem rodeios, mas dizem o que pensam de uma maneira que com frequência é extremamente embaraçosa em sua franqueza. São fortes e vigorosas em seus argumentos, seja a favor ou contra o que acreditam ou desacreditam e, por isso, recebem oposição da parte dos que diferem delas frequentemente. São muito empreendedoras e, frequentemente, se orgulham em se arriscar na busca de um prazer ou de um negócio. Quando Marte está afligido em Leão proporciona um temperamento explosivo e violento, e uma tendência para febres e doenças inflamatórias, palpitações do coração, alucinações e ser ríspida e azeda. Há, também, o perigo de afeição imoderada, problemas nos namoros, em perdas de filhos e prejuízo em especulações. Marte afligido em Leão proporciona a mesma ousadia de quando bem-aspectado, mas o perigo de acidentes é maior, porque a pessoa com Astros afligidos se torna imprudente e descuidada.`,
  'Virgem': `Marte em Virgem quando bem-aspectado proporciona uma natureza determinada em ser bem-sucedida e um intelecto rápido, capaz de entender uma ideia e trabalhar sobre ela. Fortalece as qualidades mentais; proporciona uma inclinação científica à Mente com uma habilidade para aplicar essa faculdade tanto nas atividades de pesquisas como nos negócios. A pessoa com essa posição tem, portanto, muita energia e determinação e é empreendedora em muitos dos negócios industriais do mundo. Ali, sua perspicácia e tenacidade lhe atraem êxito e prioridade em ter as melhores oportunidades. Essa é uma boa posição para as pessoas que estão engajadas em alguma atividade ligada a doentes, tais como a de enfermeira, médica, química, sanitaristas, higienistas, especialistas em preparação para alimentação específicas para cada caso de doença, alergia e tratamentos e saúde e outras ocupações semelhantes. Pessoas com Marte em Virgem, se vitimadas por uma doença, têm capacidade de se recuperar rapidamente, o que impede que se tomem inválidas crônicas como tantas outras pessoas de Virgem. Quando Marte está afligido em Virgem ele sujeita a Mente a preocupações e irritações, com uma tendência a remoer os problemas da vida, a maioria dos quais é ilusório. Não importa como ou onde tais pessoas estejam empregadas, sempre criticarão seus companheiros de trabalho e seu empregador, e estarão insatisfeitas com tudo o que se relacione com a sua função. Possuem, também, uma natureza desonesta e não se lhes pode confiar uma posição de responsabilidade. Essa posição, também, deixa a pessoa indulgente com seus apetites e a sujeita a desordens intestinais.`,
  'Libra': `Marte em Libra e bem-aspectado proporciona uma natureza amorosa ardente e disposta a mostrar que se importa com a pessoa amada, a qual é grandemente atraída para o sexo oposto, o que inclina a um casamento prematuro. Proporciona, também, um amor entusiástico pela arte e pela beleza em todas as suas fases, e tende a tornar a pessoa muito popular ante o público ou nas associações de natureza social ou religiosa. Essa é uma excelente posição para exercer a advocacia, porque gera muita atividade nesse ramo e é uma boa indicação para saúde em geral. Contudo, quando Marte está afligido em Libra tende a tornar a pessoa muito impopular e sujeita à oposição e críticas da comunidade e ao perigo de escândalo público devido à infidelidade nas relações sexuais, pois Marte em Libra sempre produz uma forte atração pelo sexo oposto, e se ele estiver afligido ali, a natureza é sensual e volúvel, com o resultado natural em ter problemas que surgirão devido a pessoa brincar com o sentimento dos outros.`,
  'Escorpião': `Marte em Escorpião quando bem-aspectado proporciona uma Mente rápida em conhecer as coisas, afiada e forte; maneiras um tanto bruscas e uma indiferença à delicada sensibilidade dos outros; consequentemente, essas pessoas se fazem a princípio desagradáveis, em muitas ocasiões, até que os outros se acostumem com elas e percebam que não são as ogras que parecem ser. São muito engenhosas e trabalhadoras, com uma coragem indomável e uma energia inesgotável que as leva a vencer todos os obstáculos, seja qual for a meta que estabeleçam para si. A esse respeito elas são muito egoístas, e prontas a sacrificar o que ou quem se interponha em seu caminho. Tendem a ser bons oficiais de polícia, soldados e cirurgiões, e são capazes de preencher qualquer outra posição onde autoridade dominante ou a destreza com instrumentos cortantes sejam exigidas. No horóscopo de uma mulher mostra que o esposo tem boa capacidade para ganhar dinheiro, embora seja generoso demais com seus recursos. Também indica a possibilidade de uma herança. Quando Marte está afligido em Escorpião, ele desvela o pior lado da natureza passional, e leva a pessoa a excessos sexuais ou a vícios solitários que minam a vitalidade, e a menos que tais vícios sejam corrigidos, ela está sujeita a encontrar uma morte prematura. No horóscopo de uma mulher indica que o esposo gastará o dinheiro gratificando-se a si mesmo e, também, que o parto será um acontecimento perigoso. Em ambos os sexos, Marte em Escorpião indica natureza uma briguenta e uma língua mordaz.`,
  'Sagitário': `Marte em Sagitário e bem-aspectado proporciona uma disposição para a argumentação e um gosto pelo debate em assuntos de natureza séria, tais como leis, filosofia e religião. Tende a tornar a pessoa que fala a verdade, mesmo quando a verdade é dura e amarga, e aberta a tudo ao lidar com os outros; cheia de entusiasmo e determinada a ser bem-sucedida, ansiosa por manter sua boa aparência aos olhos da comunidade, embora menospreze satisfazer uma necessidade que considere as ideias dos outros, onde essas não coincidam com suas ideias de probidade e justiça. Essas pessoas são interessante e ideais para entreter os outros, especialmente com os idosos ou idosas, pois gostam muito de viajar e são observadoras aguçados, sempre possuindo uma reserva de informações interessantes e instrutivas que desejam ansiosamente repartir com seus ouvintes. Essas pessoas também gostam muito de esportes e exercícios ao ar livre, nos quais sempre se sobressaem, e Marte bem-aspectado em Sagitário é uma posição ideal para exercer a advocacia. Proporciona muito sucesso nessa direção, pois aguça e estimula as faculdades mentais e a de oratória. Quando Marte está afligido em Sagitário tende a proporcionar a pessoa uma língua afiada e uma disposição briguenta, e há um traço de desonestidade em sua natureza; por isso tal pessoa é, frequentemente, pouco querida na comunidade e, particularmente, nos círculos sociais, pois, elas parecem sempre estar em desacordo com as ideias e opiniões dos outros e adotam uma atitude mais arrogante contra aqueles de quem discorda. Essas pessoas também estão sujeitas a acidentes em viagens e a sofrerem uma quantidade de fraturas ósseas.`,
  'Capricórnio': `Marte em Capricórnio quando bem-aspectado acrescenta muita força ao caráter, porque proporciona uma disposição determinada para ser bemsucedida e entusiasta, apoiada por uma coragem indomável e uma energia quase inesgotável, juntamente com uma persistente paciência e perseverança que, com certeza, vencem todos os obstáculos e, finalmente, alcançam a meta desejada. Portanto, pessoas com Marte nessa posição são determinadas a subir na vida, particularmente se Capricórnio está na 10ª Casa. Elas atraem o respeito e a estima da comunidade, de tal modo que, muitas vezes, são oferecidos empregos públicos em acréscimo aos seus empreendimentos privados para tais pessoas com tal posição; e elas servem bem em cargos de confiança porque são, naturalmente, aptas a assumir grandes responsabilidades e a levar adiante grandes empreendimentos. Quanto mais vasto seu campo de ação, mais gosto isso lhes dá, porque são superlativamente eficientes. Quando Marte está afligido em Capricórnio há idêntica determinação em ser bem-sucedida para fazer coisas grandes, mas a pessoa é insensata, impulsiva e determinada a fazer o que quer fazer, mesmo quando todos avisam que não vai dar certo, de tal maneira que se excede e põe sobre os ombros mais do que pode carregar. Falta-lhe a persistência e perseverança necessárias para vencer os obstáculos e, como a disposição é basicamente desonesta, mesmo que suba a alguma proeminência por conta de seu entusiasmo e natureza pretensiosa, é certo que logo será privada de sua autoridade, tornando-se objeto de escárnio e desdém na comunidade. Não há nada pior que Marte afligido em Capricórnio. Também expõe a acidentes que afetam os membros inferiores, e sua ação reflexa na parte do corpo que é regida pelo Signo oposto, isto é, o estômago, produz uma tendência a problemas gástricos. As pessoas com essa aflição possuem, também, um temperamento impetuoso e uma disposição vingativa.`,
  'Aquário': `Marte em Aquário quando bem-aspectado proporciona à pessoa um raciocínio perspicaz e intuitivo, criativo e original, empreendedor e determinado a ser bem-sucedido; é uma árdua trabalhadora que alcança êxito, qualquer que seja a área que escolha na vida. Por isso pode conquistar a amizade de outros que são capazes de ajudá-la a realizar suas esperanças e seus desejos. Essas pessoas são, também, muito boas em compreender o funcionamento de máquinas e engenhosas, particularmente em coisas relacionadas com as ciências elétricas. Também conseguem êxitos como administradoras, oficiais ou trabalhadoras em e para uma sociedade filantrópica ou entidade de utilidade pública. Quando Marte está afligido em Aquário ele tende a fazer a pessoa muito independente, bombástica e que se ressente facilmente com a autoridade; brusca no falar e nas maneiras nas relações com os outros; e ressentida no mais alto grau se não for tratada com o que considera ser o respeito e a consideração apropriados. Assim, é muito difícil conviver com esse tipo de pessoa e, muitas vezes, discutem com todos a sua volta. Há uma tendência para perdas em jogos e especulações. Um Marte afligido em Aquário, também, sujeita a problemas nos olhos, porque Aquário governa os Éteres, e por ação reflexa no Signo oposto, Leão, pode causar palpitações no coração.`,
  'Peixes': `Marte em Peixes quando bem-aspectado proporciona à pessoa habilidade como detetive, guarda de prisão ou cirurgiã em hospitais, e em posições semelhantes onde a pessoa não entre em contato direto com o público, mas exercite a autoridade de maneira oculta. Também imprime uma tendência a casos de amor secretos, os quais a pessoa pode ocultar do olhar público. Contudo, quando Marte está afligido em Peixes, a indulgência de tais relações sexuais clandestinas lhe acarretará problemas na vida. Há, também, risco em sofrer ataques de inimigos secretos e de se ver envolvido nas malhas da lei e ser preso, ou isso pode se manifestar como um gosto desordenado por bebidas alcoólicas fortes, que poderá levá-lo à cadeia e fazer dele um pária da sociedade. Muitos problemas e muitas desgraças são indicados, porque sua natureza é desonesta ou não verdadeira.`
};

const JUPITER_IN_SIGNS: Record<string, string> = {
  'Áries': `Júpiter em Áries torna a Mente animada, cheia de energia e determinada a ter sucesso, sempre vigilante e alerta para métodos novos e avançados que sejam úteis para o progresso ou desenvolvimento do trabalho no mundo; essa posição proporciona o verdadeiro pioneiro, nem demasiado conservador, nem excessivamente impulsivo, um ponderado, mas de temperamento simpático, sincero, honesto e digno de confiança, um tanto inclinado para a religião. Proporciona alguma aptidão para as leis e para a literatura, e gosto por jogos ao ar livre, popularidade nos círculos sociais e dos negócios. Contudo, se Júpiter estiver afligido a Mente não tende a ser tão conservadora e tão bem-equilibrada. Há uma tendência para fazer as coisas rapidamente, sem pensar cuidadosamente e agir pela impulsividade; impaciência e tendência para ficar zangado de repente ou facilmente são demonstrados sob circunstâncias adversas, com uma consequente perda de estima e popularidade.`,
  'Touro': `Júpiter em Touro quando bem-aspectado proporciona uma natureza eminentemente bondosa e compassiva para com todas as pessoas, mas um amor profundo, terno e caloroso para com aqueles cujo relacionamento justifica tal expressão. Essa posição também atrai prosperidade em recursos financeiros e produz um temperamento generoso para ajudar em empreendimentos filantrópicos; no entanto, Júpiter na 2ª Casa ou no segundo Signo nunca é esbanjador nem extravagantemente generoso, mas, ao invés disso, conservador e inclinado a investigar os méritos de qualquer pedido antes de dar a ajuda. Por outro lado, a pessoa é absolutely “mão aberta” com aqueles que a rodeiam e lhe são queridas. Seu lar e sua família são tudo para ela. Quando Júpiter está afligido em Touro inclina a gastos extravagantes em ostentação, para se exibir e gratificar a natureza inferior. Tais pessoas são grandes gastrônomos, amantes dos alimentos ricos em calorias e saborosos, que excitam o paladar. Frequentemente estão sujeitas a dificuldades financeiras e a problemas com credores, assim como a enfermidades resultantes do abuso na alimentação, segundo a outras indicações dos Astros.`,
  'Gêmeos': `Júpiter em Gêmeos quando bem-aspectado proporciona habilidade literária de alto grau, e se isto for respaldado pela educação necessária, o êxito nessa área é certo. Essa posição também proporciona uma inclinação inventiva para a Mente e uma apreciação muito forte pelas matemáticas e uma atração para o ocultismo. Júpiter em Gêmeos mostra que as viagens proporcionarão tanto prazer quanto proveito, e proporciona um temperamento honroso, cortês e amigável. Contudo, se Júpiter estiver afligido, a pessoa está sujeita a sofrer perdas e a enfrentar problemas durante suas viagens. Escapará por um fio em uma boa quantidade de acidentes; tende a ter problemas de natureza religiosa e com a lei, assim como dificuldades com irmãos, irmãs e parentes próximos.`,
  'Câncer': `Júpiter em Câncer. O efeito total de Júpiter para o bem ou para o mal nunca é sentido antes da metade da vida, e isso é especialmente o caso quando ele estiver posicionado na 4ª Casa or no quarto Signo, Câncer. Quando bem-posicionado aqui, Júpiter proporciona um temperamento extremamente afável e cortês, em paz com todo o mundo; ele dota a pessoa de uma imaginação muito vívida e fértil, uma sonhadora de sonhos utópicos, e fã incondicional do oculto e do místico. Todavia, existe também um lado prático na natureza dessas pessoas, o qual faz delas pessoas determinadas para alcançar o sucesso mundano e favorecidas em seus investimentos em casas, terras ou minas, de maneira que poderão acumular propriedades e ficar abastadas, principalmente após a meia-idade. Essa posição indica, também, que a pessoa pode receber muita ajuda de seus pais durante a vida e uma herança depois da morte deles. Júpiter em Câncer tende a fazer a pessoa muito inclinada para os deleites da mesa, mas se bem-aspectado ela se manterá dentro dos limites que não afetarão sua saúde. Todavia, se Júpiter estiver afligido, ela tende a se inclinar para gula desordenada, o que, por fim, poderá lhe intoxicar o sangue e lhe causar enfermidades e tumores malignos, como resultado de assim agir.`,
  'Leão': `Júpiter em Leão produz uma natureza verdadeiramente nobre, em que se misturam bondade e coragem, autoconfiança e lealdade, autodomínio e compaixão, perdão e justiça. Em resumo, indica um modelo de virtudes dificilmente sobrepujado. Proporciona uma abundância de vitalidade e uma forte habilidade para o seu corpo e sua saúde combater as doenças, de tal modo que marcam um líder do ponto de vista espiritual, moral e fisicamente, uma pessoa que não iria se contentar em seguir as outras. Almejam posições de confiança e responsabilidade, quanto maior melhor. Serão sempre as mesmas em qualquer ocasião e não abusarão da confiança daqueles que as puseram ali. Tais pessoas possuem uma cultura e um refinamento inatos. Gostam de todas as coisas que tendam à elevação da humanidade; são religiosas e sinceras; por certo ganham o reconhecimento dos outros e obtêm êxito ao investirem em negócios especulativos. Quando Júpiter está afligido em Leão, a pessoa tende a se tornar cruel e sensual, com atração anormal por divertimentos e sujeita a perder em investimentos, especulação e jogo de azar.`,
  'Virgem': `Júpiter em Virgem proporciona uma natureza cautelosa, analítica e prática, com uma faculdade quase infalível de distinguir entre o aparente e o real, para examinar cuidadosamente a fim de decidir onde é verdade e onde não é para chegar aos fatos. Tais pessoas não podem arrancar segredos por métodos ardilosos, como Saturno em Capricórnio, que proporciona um detetive ideal, mas se Júpiter em Virgem é o juiz, ninguém será bastante esperto para lhe ocultar a verdade. Um Júpiter bem-aspectado em Virgem indica êxito com empregados, que serão fiéis, leais e prontos para executar as ordens de seu patrão. Também indica prosperidade em negócios ou na profissão; no entanto, se Júpiter está afligido em Virgem, então há tendência para um temperamento cínico, crítico, dada à censura, desconfiado dos outros e, portanto, sujeito a prejuízos causados por empregados e funcionários. Tais pessoas não podem ter êxito em negócios, e acharão extremamente difícil obter ou manter uma boa posição. De qualquer modo, servirão em funções muito inferiores.`,
  'Libra': `Júpiter em Libra quando bem-aspectado produz um temperamento afável, compassivo e simpático, uma natureza conscienciosa, sociável e benevolente, e um interesse por tudo que vise a elevação da humanidade, como a música, arte, literature, as relações sociais, etc. Por essa razão a pessoa é popular, particularmente entre o sexo oposto, do qual pode esperar vantagens e benefícios. Há boas tendências para obter êxitos nos negócios e na vida pública. Contudo, se Júpiter estiver afligido em Libra, uma indulgência excessiva com a natureza inferior pode ocasionar problemas e escândalo público, com a consequente perda de popularidade e prestígio.`,
  'Escorpião': `Júpiter em Escorpião proporciona uma natureza ardente, agressiva e confiante em si mesma; uma Mente entusiasta, construtiva e com muitos recursos, com a habilidade para enfrentar todas as exigências da vida de uma maneira eficaz, e isso assegura o êxito nas ocupações práticas de cada dia, proporciona uma família numerosa, e tende a promover a abundância de meios para mantê-la. Esta posição, também, mostra uma tendência para as investigações ocultas. No entanto, se Júpiter estiver afligido em Escorpião tenderá a trazer perdas e problemas por indulgência com a natureza inferior de modo desordenado, e preferência por alimentos ricos em calorias e caros, que resultarão em enfermidades.`,
  'Sagitário': `Júpiter em Sagitário quando bem-aspectado proporciona boas oportunidades com sucesso nos resultados e facilidade, em geral, em obter aquilo que deseja ou pretende na vida; uma Mente humanitária, ampla e filosófica, e um temperamento religioso e reverente. Com isso, pessoas com essa posição se elevam ao máximo e se tornam líderes nas várias esferas da vida, ocupando lugares proeminentes na igreja ou no estado, em instituições ou empreendimentos científicos ou filosóficos. Se Júpiter estiver afligido em Sagitário, então tende a fazer a pessoa alguém que goste muito de esportes e é bom neles, gostando de se exibir com coisas baratas e espalhafatosas, extravagante e pronto para aproveitar oportunidades em qualquer jogo, causa da perda da posição social, se nascido em ambiente apropriado para tal, dos problemas com a justiça, das dificuldades financeiras e, se for um religioso, não disposto a aceitar ou entender ideias, opiniões ou novos costumes ou diferentes daqueles que já têm.`,
  'Capricórnio': `Júpiter em Capricórnio proporciona à pessoa uma natureza determinada a ser bem-sucedida, autoconfiante e autocontrolada, com um desejo de obter a uma posição elevada de autoridade sobre os outros, assim como uma boa e sábia habilidade para dizer as outras pessoas exatamente o que deve ser feito e como fazer. Proporciona um temperamento cuidadoso, econômico, e uma aversão ao desperdício; habilidade para inventar coisas e pensar em novas ideias; muito boa para achar modos de lidar com problemas práticos; e alguma capacidade mecânica. Essas pessoas são dignas de confiança, sinceras e honestas em todos os seus empreendimentos, e sustentam qualquer promessa que tenham feito, e por isso, geralmente, crescem em hora, estima e popularidade geral. Conforme dito acima, o objetivo dessas pessoas é obter a independência à frente de algum negócio, porém, se nisso não forem bem-sucedidas e tiverem que trabalhar para outros, elas melhor se adaptarão a serviços no governo, quer municipal, estadual ou federal. Devido à confiança implícita gerada por suas genuínas características de honestidade, sinceridade e fidelidade, essas pessoas se tornam, frequentemente, depositários da confiança de amigos, os quais sentem necessidade de dividir seus problemas com alguém que lhes possa aconselhar, honesta e desinteressadamente, e manter invioláveis os segredos confiados. Se Júpiter estiver afligido em Capricórnio, então tende a tornar a pessoa uma miserável, que junta tudo o que pode acumular e nada gasta consigo mesmo, exceto nas necessidades mais básicas, e em consequência é desprezada por todos que a conhecem.`,
  'Aquário': `Júpiter em Aquário quando bem-aspectado proporciona uma Mente humanitária, otimista, original e filosófica, afeiçoada aos amigos e à sociedade com os outros, particularmente com aqueles que se interessam por ciência ou misticismo, por literatura e música; consequentemente, a pessoa atrai outras de mesma natureza, as quais lhe serão benéficas ao ajudá-la a realizar suas esperanças, seus desejos e suas ambições. Poderá obter, possivelmente, uma posição de importância em algum cargo oficial em sociedades secretas ou ocultas. Esta é uma boa indicação de êxito geral na vida; mas se Júpiter estiver afligido, então a natureza será inquieta, nervosa e errática, com ideias revolucionárias ou anarquistas e com aversão ao trabalho sério, e tais pessoas, geralmente, são detestadas e nelas não se pode confiar.`,
  'Peixes': `Júpiter em Peixes proporciona uma natureza caridosa, compassiva e hospitaleira, que gosta muito de contribuir para os desamparados da sociedade. Essas pessoas são verdadeiros anjos de misericórdia para com os que sofrem do corpo, da alma e do espírito. Elas são bem-conhecidas daqueles que vivem “doentes ou aprisionados”. Como são de natureza sensitiva e sujeitas às influências dos Mundos invisíveis, tendem a ter frequentes experiências psíquicas e se tornam estudantes do ocultismo. Amam a música, a arte e a literatura, e se bem-aspectado por Vênus, Júpiter em Peixes proporcionará uma considerável habilidade para representar artisticamente; contudo, se Júpiter estiver afligido em Peixes, então tenderá a ter uma Mente vacilante, uma natureza sem força e sem energia, covarde, pronta para se deliciar com todos os vícios que se pode programar na sua vida, e, geralmente, um temperamento extremamente inclinado para o mal e para a crueldade – um parasita da sociedade.`
};

const SATURN_IN_SIGNS: Record<string, string> = {
  'Áries': `Saturno em Áries é fraco e, portanto, incapaz de expressar suas melhores qualidades em sua completa e legítima medida mesmo que esteja bem-aspectado. Ainda assim ele proporciona, em menor extensão, uma maneira calma e confiante de se comportar – com a capacidade de controlar seus sentimentos ou suas reações em situações difíceis –, autoconfiança, discrição e tato, trabalhar arduamente, paciência e perseverança. Contudo, quando Saturno está afligido em Áries, a pessoa se irrita facilmente e é capaz de guardar rancor, e, também, de expressar uma disposição ciumenta, mal-intencionada e vingativa.`,
  'Touro': `Saturno em Touro quando bem-aspectado torna a pessoa lenta ao falar, mas o que ela diz tem peso e é digno de ser ouvida. Proporciona uma disposição calma, lenta para decidir, mas obstinada em manter sua decisão, uma vez tomada. Essas pessoas falam pouco e podem ser confiáveis para manter tanto os seus segredos como os dos outros. Quando Saturno está afligido em Touro, particularmente por Mercúrio, sempre causa problemas com a fala e gera uma tendência a se zangar de repente ou facilmente, especialmente se Marte também se acha afligido. Essa posição produz dificuldades financeiras.`,
  'Gêmeos': `Saturno em Gêmeos quando bem-aspectado proporciona uma Mente profunda, aguçada, disciplinada, científica, adaptável às circunstâncias e capaz de lidar com todas as exigências da vida. O amor pela matemática é, geralmente, pronunciado e quando escolhe a literatura como vocação, os setores mais sérios, consagrados a assuntos industriais e mecânicos, são os preferidos. Quando Saturno está afligido em Gêmeos temos problemas com: irmãos e irmãs, a instrução primária, a lei, e o perigo em viagens curtas. Um Saturno afligido em Gêmeos também indica problema nos pulmões. Tais pessoas devem, pois, se cuidar para não pegar gripes.`,
  'Câncer': `Saturno em Câncer é sempre fraco, e suas virtudes encontram dificuldades de expressão, quando ele aqui se encontra. Contudo, proporciona juízo confiável no que diz respeito a casas, terras, minas, etc., e ganhos por investimento nessas coisas; quando bem-aspectado, favorece um sábio e cuidadoso uso do dinheiro – nada é desperdiçado –, a economia e um real, prático e contínuo conforto no lar com condições tranquilas, pacíficas e confortáveis na última parte da vida. Torna a pessoa frugal e proporciona bom controle do apetite. Contudo, quando afligido, indica infelicidade doméstica, sendo a pessoa impedida de progredir na vida por um cônjuge depressivo, desmancha-prazeres, que sempre restringe qualquer pensamento determinado a ter sucesso em alguma coisa. Problemas, grandes tristezas e decepções aumentam à medida que a vida passa, e a isso se acrescenta uma saúde precária, de modo que Saturno em Câncer indica que o estômago é fraco e as gengivas sujeitas à piorreia, havendo, consequentemente, uma incapacidade para digerir bem os alimentos; assim, a menos que essas pessoas tenham vontade suficiente para controlar seus apetites, serão vítimas de indigestão crônica. Saturno em Câncer indica também tendência religiosa e inclinação para o estudo das ciências mais profundas.`,
  'Leão': `Saturno em Leão quando bem-aspectado favorece a ajuda de pessoas em posição superior na escala social e êxito na obtenção de empregos públicos onde as virtudes saturninas do tato, da diplomacia, da discrição e do método, da honra e da habilidade executiva são os atributos necessários. A saúde e a capacidade do corpo em lutar contra as doenças e enfermidades dessas pessoas não é muito forte, mas elas podem manter uma saúde perfeita pela conservação de energia, conforme indicado por Saturno. Quando, porém, Saturno está afligido em Leão, essas pessoas são cruéis, se irrita facilmente, ciumentas e sem escrúpulos de se rebaixarem a ponto de usarem meios desonestos para satisfazer uma ambição. Essa posição também indica problemas cardíacos.`,
  'Virgem': `Saturno em Virgem proporciona uma Mente estudiosa, profunda e científica, apta para estudar os problemas mais sérios da vida. Indica habilidade inata para dirigir os outros. Produz uma natureza: sábia e cuidadosa no uso do dinheiro – nada é desperdiçado –, econômica e frugal; mas quando Saturno está afligido nesse Signo, geralmente a Mente se concentra nas doenças, de modo que a pessoa se converte em uma hipocondríaca convicta. Essas pessoas são os melhores fregueses dos vendedores de remédios, pois muitas de suas doenças são, geralmente, imaginárias. Essa posição, no entanto, cria propensão a doenças intestinais.`,
  'Libra': `Saturno em Libra está em seu Signo de Exaltação e muito forte e, portanto, seus bons Aspectos produzem todas as melhores qualidades saturninas e, por essa razão assegura à pessoa a estima e o reconhecimento públicos. O cônjuge é casto e puro como ouro. Essa posição resulta também em boa saúde e vida longa, mas quando Saturno está afligido nesse Signo, o cônjuge é desleal ou é levado por morte prematura. Se a pessoa recorre à justiça, é quase certo que perderá, e se torna objeto de desprezo público. Também estará sujeita a problemas urinários.`,
  'Escorpião': `Saturno em Escorpião quando bem-aspectado proporciona uma Mente com rara aptidão mecânica, ampla em recursos sob as mais difíceis condições, uma coragem indomável e uma persistência paciente diante da qual, até os problemas de mais difícil solução são resolvidos. Daí tais pessoas se constituírem nos engenheiros mais capacitados e são de valor inestimável em qualquer empreendimento pioneiro; misturam o fogo de Marte com a previsão de Saturno e são, portanto, invencíveis. Eles ganham por meio de heranças, por meio da economia e por meio de um sábio e cuidadoso uso do dinheiro – onde nada é desperdiçado, e seus lastros financeiros aumentam muito depois do casamento. Boa saúde e uma longa vida são também indicados, mas quando Saturno está afligido nesse Signo, o cônjuge é pobre, lento, egoísta e exigente, e a pessoa está sujeita a preocupações e à má saúde; constipação e hemorroidas são as causas básicas que afetam os nervos e todo o sistema.`,
  'Sagitário': `Saturno em Sagitário quando bem-aspectado proporciona uma disposição caridosa e filantrópica, com um desejo de que a humanidade se eleve por si mesma sob leis justas e impulsos religiosos verdadeiros. Saturno em Sagitário combina todas as virtudes saturninas com o benevolente espírito de aspiração jupiteriano, de modo que tais pessoas sempre almejam trabalhar para o bem geral, conforme suas habilidades e posição na vida. Portanto, são dignas de confiança, honradas, respeitadas e muito requisitadas para ocupar cargo em que tais qualidades são valiosas, no âmbito social, industrial e religioso. Quando Saturno está afligido em Sagitário proporciona uma pessoa falsa, cínica e sarcástica, ambiciosa para ocupar postos honrosos e de confiança, mas com propósitos egoístas; propensa a se envolver com a lei e a perder a causa, em consequência disso. Essa posição também afeta os pulmões, motivo pelo qual a pessoa deve ter muito cuidado para não pegar gripes.`,
  'Capricórnio': `Saturno em Capricórnio quando bem-aspectado é forte pelo que suas virtudes são igualmente marcantes, com honestidade e integridade tão firmes como o Rochedo de Gibraltar, e a determinação de avançar rumo à meta desejada não importando quanto tempo isso possa levar. Daí que, a despeito de todos os empecilhos e obstáculos, as pessoas com Saturno bem-aspectado em Capricórnio alcançam, finalmente, uma grande quantidade de sucesso, sendo geralmente estimados por seus contemporâneos. Quando Saturno está afligido nesse Signo, a Mente é envolvida por grande tristeza e a pessoa vê a vida sob um ponto de vista tendencioso. Há uma sensação geral de insatisfação que, às vezes, evolui para uma Mente doentia. Tais pessoas são astutas, desleais e não são de confiança.`,
  'Aquário': `Saturno em Aquário quando bem-aspectado proporciona uma disposição simpática e amistosa, uma linguagem muito clara e cuidadosa e uma seriedade em todos os assuntos da vida. Essas pessoas, portanto, fazem amigos entre os idosos, os ricos e os intelectuais, que são capazes de ajudá-las a subir na vida. Contudo, quando Saturno está afligido em Aquário, proporciona uma disposição arguta, astuta e pronta para enganar os outros ao lhe conquistar a confiança e amizade e, tais pessoas, pois, se afundam até os níveis mais baixos da sociedade. Essa posição indica, também, uma tendência a problemas cardíacos e veias varicosas.`,
  'Peixes': `Saturno em Peixes quando bem-aspectado proporciona uma tendência para o sucesso em algum setor da vida que seja calmo e pacífico, onde essas pessoas não tenham contato com o público, tais como trabalhos em laboratórios, com pesquisas ou relacionados com instituições encarregadas dos desamparados da comunidade; normalmente são caseiras, contudo, quando Saturno está afligido nesse Signo, há o perigo de confinamento por uma doença crônica ou possibilidade de encarceramento. A pessoa faz muitos inimigos, os quais serão persistentes em persegui-la.`
};

export function getPlanetInSignInterpretation(planetName: string, signName: string): string {
  if (planetName === 'Sol' && SUN_IN_SIGNS[signName]) {
    return SUN_IN_SIGNS[signName];
  }
  
  if (planetName === 'Lua' && MOON_IN_SIGNS[signName]) {
    return MOON_IN_SIGNS[signName];
  }

  if ((planetName === 'Mercúrio' || planetName === 'Mercurio') && MERCURY_IN_SIGNS[signName]) {
    return MERCURY_IN_SIGNS[signName];
  }

  if ((planetName === 'Vênus' || planetName === 'Venus') && VENUS_IN_SIGNS[signName]) {
    return VENUS_IN_SIGNS[signName];
  }

  if ((planetName === 'Marte' || planetName === 'Marte') && MARS_IN_SIGNS[signName]) {
    return MARS_IN_SIGNS[signName];
  }

  if ((planetName === 'Júpiter' || planetName === 'Jupiter') && JUPITER_IN_SIGNS[signName]) {
    return JUPITER_IN_SIGNS[signName];
  }

  if ((planetName === 'Saturno' || planetName === 'Saturn') && SATURN_IN_SIGNS[signName]) {
    return SATURN_IN_SIGNS[signName];
  }

  // Retorna um texto de placeholder explicativo da presença do planeta no signo para os outros astros
  return `A presença de ${planetName} no signo de ${signName} matiza a energia deste astro com as qualidades essenciais de ${signName}. 

(Placeholder) Aqui você pode descrever como a natureza de ${planetName} (ex: comunicação, emoção, ação) se expressa através do filtro de ${signName} (ex: de forma pragmática se for um signo de terra, de forma emocional se for água, de forma explosiva se for fogo, ou intelectual se for ar). Esta combinação específica marca a forma fundamental como este aspecto opera em seu mapa.`;
}
